export const getCreateGroupApplyUrl = (id: string,) => {




  return `/api/groups/${id}/applies`
}

/**
 * Requires an `Idempotency-Key` header. Same key and body replays the original operation with `200`; same key with a different body is `422 IDEMPOTENCY_KEY_REUSED`; an apply while one is running is `409 OPERATION_IN_PROGRESS`.
 * @summary Apply the group's desired state
 */
export const createGroupApply = async (id: string,
    applyInput: ApplyInput, options?: Parameters<typeof customFetch>[1]): Promise<Operation> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Operation>(getCreateGroupApplyUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(applyInput)
  }
);}





export const getCreateGroupApplyMutationKey = () => ['createGroupApply'] as const;

